// ============================================================
// Search targets. Keywords in the same sub are OR-grouped into
// batches of KEYWORDS_PER_QUERY so we cover many more phrases
// with fewer Reddit requests.
// sub: null  => site-wide Reddit search (all subreddits)
// ============================================================
const KEYWORDS_PER_QUERY = 3;
const RESULTS_PER_FEED = 100; // Reddit default is 25

const targets = [
  // ---------- Payments communities (best conversion) ----------
  { sub: 'PaymentProcessing', keywords: ['merchant account terminated', 'MID terminated', 'high risk processor', 'rolling reserve', 'approval rate', 'decline rate', 'payment orchestration', 'chargeback ratio', 'funds held', 'iGaming', 'peptide', 'nutra'] },
  { sub: 'merchantservices', keywords: ['high risk', 'merchant account terminated', 'frozen funds', 'approval rate', 'rolling reserve', 'MATCH list'] },
  { sub: 'payments', keywords: ['high risk', 'PSP recommendation', 'chargeback', 'cross-border', 'payment orchestration', 'acquirer'] },
  { sub: 'fintech', keywords: ['multi PSP', 'payment orchestration', 'white label PSP', 'smart routing', 'high risk payments', 'acquiring'] },
  { sub: 'Stripe', keywords: ['account closed', 'funds held', 'high risk', 'alternative to Stripe', 'rejected', 'reserve'] },
  { sub: 'paypal', keywords: ['account limited', 'funds held', 'alternative to PayPal', '180 days'] },

  // ---------- iGaming ----------
  { sub: 'iGaming', keywords: ['payment processor', 'PSP', 'chargeback', 'approval rate', 'FTD', 'payment provider'] },
  { sub: 'gambling', keywords: ['casino payment processor', 'sportsbook payments', 'operator payments'] },
  { sub: 'sportsbook', keywords: ['payment processor', 'payment provider', 'white label'] },
  { sub: 'onlinegambling', keywords: ['payment processor', 'payment provider', 'operator'] },

  // ---------- Forex / trading ----------
  { sub: 'Forex', keywords: ['payment processor', 'PSP', 'broker payments', 'deposit problems'] },
  { sub: 'algotrading', keywords: ['prop firm payment processor', 'prop firm Stripe'] },
  { sub: 'Daytrading', keywords: ['prop firm payment processor'] },

  // ---------- Adult ----------
  { sub: 'SexWorkers', keywords: ['payment processor', 'merchant account', 'CCBill'] },
  { sub: 'onlyfansadvice', keywords: ['payment processor', 'own site payments', 'CCBill'] },

  // ---------- Nutra / CBD / Peptides ----------
  { sub: 'CBD', keywords: ['payment processor', 'merchant account', 'high risk processor'] },
  { sub: 'hempflowers', keywords: ['payment processor', 'merchant account'] },
  { sub: 'Peptides', keywords: ['payment processor', 'merchant account', 'Stripe'] },
  { sub: 'Supplements', keywords: ['payment processor', 'merchant account', 'Stripe banned'] },
  { sub: 'Nootropics', keywords: ['payment processor', 'merchant account'] },

  // ---------- Merchants / eCommerce ----------
  { sub: 'ecommerce', keywords: ['high risk payment', 'merchant account terminated', 'Stripe banned', 'payment processor recommendation', 'chargebacks', 'rolling reserve'] },
  { sub: 'shopify', keywords: ['Shopify Payments disabled', 'high risk', 'third party payment gateway'] },
  { sub: 'woocommerce', keywords: ['high risk gateway', 'payment gateway recommendation', 'Stripe banned'] },
  { sub: 'smallbusiness', keywords: ['merchant account terminated', 'high risk processor', 'funds held'] },
  { sub: 'Entrepreneur', keywords: ['payment processor', 'merchant account', 'Stripe banned'] },
  { sub: 'SaaS', keywords: ['payment processor', 'Stripe banned'] },
  { sub: 'affiliatemarketing', keywords: ['FTD', 'iGaming payments', 'nutra offer payments'] },

  // ---------- Site-wide high-intent phrases (no subreddit) ----------
  { sub: null, keywords: [
    'high risk merchant account', 'MID terminated', 'rolling reserve processor',
    'casino payment processor', 'sportsbook payment processor', 'iGaming PSP',
    'forex payment processor', 'CFD broker PSP', 'prop firm payment processor',
    'adult payment processor', 'CBD merchant account', 'peptide payment processor',
    'nutra merchant account', 'high risk payment gateway', 'payment orchestration platform',
    'white label PSP', 'crypto on ramp provider', 'looking for acquirer'
  ] }
];

function chunk(arr, size) {
  const out = [];
  for (let i = 0; i < arr.length; i += size) out.push(arr.slice(i, i + size));
  return out;
}

const results = [];
let counter = 1;

for (const target of targets) {
  for (const group of chunk(target.keywords, KEYWORDS_PER_QUERY)) {
    // "a b" OR "c d" -> phrase search, any of the phrases
    const query = group.map(k => `"${k.trim()}"`).join(' OR ');
    const base = target.sub
      ? `https://www.reddit.com/r/${target.sub}/search.rss?restrict_sr=1&`
      : `https://www.reddit.com/search.rss?`;

    results.push({
      json: {
        id: counter++,
        subreddit: target.sub || 'all',
        searchQuery: group.join(' | '),
        feedUrl: `${base}q=${encodeURIComponent(query)}&sort=new&t=month&limit=${RESULTS_PER_FEED}`,
        useProxy: true,
        generatedAt: new Date().toISOString()
      }
    });
  }
}

return results;
